package net.officefloor.hq.app.person;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

/** Put a person on hold from a from-date (blank: the sheet's today) to an optional to-date. A person may
 *  have several holds; each ends on its to-date. Their open (OPEN or PENDING) claims dated within a hold,
 *  unless bound by a statement, count in no live total; their other claims still do. */
public class HoldPerson {
    public void hold(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
            @Val HoldInput input, ServerHttpConnection connection, PersonRepository repository,
            SheetRepository sheets, Audit audit, Rollup rollup, Out<Person> person) throws BadRequestException {
        String by = CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        long pid;
        try {
            pid = Long.parseLong(personId == null ? "" : personId.trim());
        } catch (NumberFormatException e) {
            throw new BadRequestException("no such person");
        }
        Person found = repository.find(id, pid);
        if (found == null) {
            throw new BadRequestException("no such person");
        }
        LocalDate from = input.from() != null ? input.from() : sheets.today(id);
        if (input.to() != null && input.to().isBefore(from)) {
            throw new BadRequestException("to must not be before from");
        }
        Rollup.Snapshot before = rollup.take(id);
        repository.hold(id, pid, from, input.to());
        audit.record("PERSON_HELD sheet=" + id + " by=" + by + " name=" + found.name() + " from=" + from);
        rollup.record(id, by, before);
        person.set(repository.find(id, pid));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.CurrentUser;
import net.officefloor.plugin.variable.Out;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadPeople {
    public void load(@PathVariable("sheetId") String sheetId, ServerHttpConnection connection,
            PersonRepository repository, PatronRepository patrons, Out<People> people) throws BadRequestException {
        CurrentUser.require(connection);
        String id = sheetId == null ? "" : sheetId.trim();
        people.set(new People(repository.list(id), patrons.list(id)));
    }
}
package net.officefloor.hq.app.person;

import java.util.List;

/** A person on a sheet: the id the store assigned, their name and the grade (A, B or C) in force on
 *  the sheet's today, with every grade they have been given (oldest first), and the
 *  version of these values (up by one on each save), and their statements: how many have been taken,
 *  and the last one's due-total and date (both null before the first), and the date they are retired
 *  from (null when not retired; any date set means retired at once), and their holds (oldest first) and
 *  whether they have any (their open (OPEN or PENDING) claims dated within a hold, unless bound by a
 *  statement, then count in no live total). */
public record Person(long id, String name, String grade, long version, long statementCount,
        String statedTotal, String statementDate, String retiredFrom, boolean held, List<GradeFrom> grades,
        List<Hold> holds) {

    public Person withGrades(List<GradeFrom> grades) {
        return new Person(id, name, grade, version, statementCount, statedTotal, statementDate, retiredFrom, held, grades, holds);
    }

    public Person withHolds(List<Hold> holds) {
        return new Person(id, name, grade, version, statementCount, statedTotal, statementDate, retiredFrom,
                !holds.isEmpty(), grades, holds);
    }

